mapper.select:
select 'leadTotal' metricKey, count(*) metricValue, coalesce(sum(ifnull(l.estimated_amount,0)),0) amountValue from biz_lead l where l.del_flag='0' and l.create_time >= #{beginDate} and l.create_time < date_add(#{endDate}, interval 1 day)
union all select 'convertedLeads', count(*), coalesce(sum(ifnull(l.estimated_amount,0)),0) from biz_lead l where l.del_flag='0' and l.status='3' and l.converted_time >= #{beginDate} and l.converted_time < date_add(#{endDate}, interval 1 day)
union all select 'linkedCustomers', count(distinct l.customer_id), coalesce(sum(ifnull(l.estimated_amount,0)),0) from biz_lead l where l.del_flag='0' and l.status='3' and l.customer_id is not null and l.converted_time >= #{beginDate} and l.converted_time < date_add(#{endDate}, interval 1 day)
union all select 'signedCustomers', count(distinct c.customer_id), coalesce(sum(ifnull(c.sign_amount,0)),0) from biz_contract c where c.del_flag='0' and c.sign_status in ('1','2') and c.sign_date >= #{beginDate} and c.sign_date <= #{endDate}
union all select 'signedContracts', count(distinct c.contract_id), coalesce(sum(ifnull(c.sign_amount,0)),0) from biz_contract c where c.del_flag='0' and c.sign_status in ('1','2') and c.sign_date >= #{beginDate} and c.sign_date <= #{endDate}

select , concat('HK', date_format(ifnull(p.update_time, p.create_time), '%Y%m%d'), lpad(p.plan_id, 4, '0')) paymentNo, p.update_time paymentDate, p.finance_user_id financeUserId from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id left join biz_case ca on ca.contract_id=c.contract_id and ca.del_flag='0' left join sys_user u on u.user_id=c.owner_id
and c.del_flag='0' and (c.contract_no like concat('%',#{keyword},'%') or ca.case_no like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%')) and p.confirm_status=#{confirmStatus} and c.owner_id=#{ownerId} and coalesce(p.update_time, p.plan_receive_date, p.create_time) >= #{beginDate} and coalesce(p.update_time, p.plan_receive_date, p.create_time) < date_add(#{endDate}, interval 1 day)
order by case when p.confirm_status='0' then 0 else 1 end, p.update_time desc, p.plan_id desc limit #{dashboardLimit}

select e.*, c.case_no caseNo, c.case_name caseName, c.customer_name customerName, c.contract_no contractNo,
       c.case_type caseType, c.case_status caseStatus, c.main_lawyer_name mainLawyerName,
       ct.contract_name contractName, ct.sign_amount contractSignAmount
from biz_case_expense e
left join biz_case c on c.case_id=e.case_id
left join biz_contract ct on ct.contract_id=c.contract_id and ct.del_flag='0'

    and e.del_flag='0' and c.del_flag='0'
    and (e.expense_no like concat('%',#{keyword},'%') or c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%'))
    and e.case_id=#{caseId}
    and e.expense_type=#{expenseType}
    and e.pay_status=#{payStatus}
    and e.reimburse_status=#{reimburseStatus}
    and e.voucher_status=#{voucherStatus}
    and e.occur_date >= #{beginDate}
    and e.occur_date <= #{endDate}


order by e.occur_date desc, e.expense_id desc

select 'income' metricKey, coalesce(sum(case when p.confirm_status='1' then p.received_amount else 0 end),0) metricValue from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id where c.del_flag='0' and p.update_time >= #{beginDate} and p.update_time < date_add(#{endDate}, interval 1 day)
union all select 'cost', coalesce(sum(e.amount),0) from biz_case_expense e left join biz_case c on c.case_id=e.case_id where e.del_flag='0' and c.del_flag='0' and e.occur_date >= #{beginDate} and e.occur_date <= #{endDate}
union all select 'arrears', coalesce(sum(greatest(p.receivable_amount - ifnull(case when p.confirm_status='1' then p.received_amount else 0 end,0),0)),0) from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id where c.del_flag='0' and p.plan_receive_date >= #{beginDate} and p.plan_receive_date <= #{endDate}
union all select 'invoicePending', coalesce(sum(case when p.confirm_status='1' and p.invoice_status in ('0','2') then p.received_amount else 0 end),0) from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id where c.del_flag='0' and p.update_time >= #{beginDate} and p.update_time < date_add(#{endDate}, interval 1 day)
